from enum import Enum
from typing import Any, Optional

from flet.core.constrained_control import ConstrainedControl, OptionalNumber
from flet.core.event_handler import EventHandler
from flet.core.ref import Ref
from flet.core.types import OptionalEventCallable


class LensDirection(Enum):
    BACK = "back"
    FRONT = "front"


class NativeCamera(ConstrainedControl):
    """
    A control that shows a live, in-app camera preview and can capture a
    still photo from it, backed by the Flutter `camera` plugin -- replaces
    OpenCV's cv2.VideoCapture, which has no iOS build at all.

    Unlike a system-camera-app handoff, this renders inline wherever it's
    placed (e.g. inside a Stack in the caller's own preview box), matching
    how the old OpenCV-based camera looked. Call start()/start_async() to
    begin the live preview and stop()/stop_async() to release the hardware
    (e.g. before leaving the view or rebuilding it in place).
    """

    def __init__(
        self,
        lens_direction: LensDirection = LensDirection.BACK,
        on_error: OptionalEventCallable = None,
        #
        # ConstrainedControl
        #
        ref: Optional[Ref] = None,
        width: OptionalNumber = None,
        height: OptionalNumber = None,
        expand: Any = None,
        visible: Optional[bool] = None,
        data: Any = None,
    ):
        ConstrainedControl.__init__(
            self,
            ref=ref,
            width=width,
            height=height,
            expand=expand,
            visible=visible,
            data=data,
        )
        self.__on_error = EventHandler(lambda e: e)
        self._add_event_handler("error", self.__on_error.get_handler())

        self.lens_direction = lens_direction
        self.on_error = on_error

    def _get_control_name(self):
        return "native_camera"

    def start(self, wait_timeout: Optional[float] = 10) -> bool:
        started = self.invoke_method(
            "start",
            {"lensDirection": self._lens_direction_value()},
            wait_for_result=True,
            wait_timeout=wait_timeout,
        )
        return started == "true"

    async def start_async(self, wait_timeout: Optional[float] = 10) -> bool:
        started = await self.invoke_method_async(
            "start",
            {"lensDirection": self._lens_direction_value()},
            wait_for_result=True,
            wait_timeout=wait_timeout,
        )
        return started == "true"

    def stop(self, wait_timeout: Optional[float] = 5) -> None:
        self.invoke_method("stop", wait_for_result=True, wait_timeout=wait_timeout)

    async def stop_async(self, wait_timeout: Optional[float] = 5) -> None:
        await self.invoke_method_async(
            "stop", wait_for_result=True, wait_timeout=wait_timeout
        )

    def take_picture(self, wait_timeout: Optional[float] = 15) -> Optional[bytes]:
        path = self.invoke_method(
            "take_picture", wait_for_result=True, wait_timeout=wait_timeout
        )
        return self._read_bytes(path)

    async def take_picture_async(
        self, wait_timeout: Optional[float] = 15
    ) -> Optional[bytes]:
        path = await self.invoke_method_async(
            "take_picture", wait_for_result=True, wait_timeout=wait_timeout
        )
        return self._read_bytes(path)

    @staticmethod
    def _read_bytes(path: Optional[str]) -> Optional[bytes]:
        if not path:
            return None
        with open(path, "rb") as f:
            return f.read()

    def _lens_direction_value(self) -> str:
        value = self.lens_direction
        return value.value if isinstance(value, LensDirection) else value

    # lens_direction
    @property
    def lens_direction(self):
        return self._get_attr("lensDirection", def_value=LensDirection.BACK.value)

    @lens_direction.setter
    def lens_direction(self, value):
        self._set_enum_attr("lensDirection", value, LensDirection)

    # on_error
    @property
    def on_error(self):
        return self.__on_error.handler

    @on_error.setter
    def on_error(self, handler: OptionalEventCallable):
        self.__on_error.handler = handler
